member.example:
Solve the 1D Heat Conduction Equation:
.. math::

   \frac{\partial u}{\partial t} = 0.5 \frac{\partial^2 u}{\partial x^2}, \quad x \in [0, 1], \; t \in [0, 0.5]

With initial condition :math:`u(x, 0) = \sin(\pi x)` and Dirichlet boundary conditions :math:`u(0, t) = 0, u(1, t) = 0`.

    using SepalSolver.Math;
    using static System.Math;

    int m = 0;
    double[] x = Linspace(0,1,51);
    double[] t = Linspace(0,0.5,6);;

    (double c, double f, double s) PdeFun(double x, double t, double u, double dudx) 
        => (1.0, 0.5 * dudx, 0.0);

    double IcFun(double x) => Sin(pi * x);

    (double pl, double ql, double pr, double qr) BcFun(double xl, double ul, double xr, double ur, double t) 
        => (ul, 0.0, ur, 0.0);

    (ColVec T, Matrix U) = pdepe(m, PdeFun, IcFun, BcFun, x, t);

    PlotSurface(x, T, U);
    Title("1D Heat Equation Solution");
    Xlabel("Position x");
    Ylabel("Time t");
    SaveAs(Path + "HeatEquation.png");

   .. math::
      X = [1, 2, 3, 4],~ Y = [1, 4, 9, 16],~ N = 2
In this example, we fit a polynomial of degree 2 to the data points.
The x-coordinates are represented by the array { 1, 2, 3, 4 } and the y-coordinates by { 1, 4, 9, 16 }.

   // import libraries
   using System;
   using SepalSolver.Math;

   // Example of fitting a polynomial
   double[] X = { 1, 2, 3, 4 };
   double[] Y = { 1, 4, 9, 16 };
   int N = 2;
   double[] coefficients = Polyfit(X, Y, N);
   // Print the result
   Console.WriteLine($"Coefficients: {string.Join(", ", coefficients)}");


   Coefficients: 1, 0, 0

   .. math::
       P(x) = 1x^2 + 0x + 5, ~ Q(x) = 3x + 2
In this example, we add a 2nd-degree polynomial to a 1st-degree polynomial.
The input arrays would be { 1, 0, 5 } and { 3, 2 }.

   // import libraries
   using System;
   using static SepalSolver.Math;

   // Example of adding two polynomials
   double[] poly1 = [1, 0, 5]; // x^2 + 5
   double[] poly2 = [3, 2];    // 3x + 2
   double[] result = Polyadd(poly1, poly2);

   // Print the result
   Console.WriteLine($"Resulting Coefficients: {string.Join(", ", result)}");


   Resulting Coefficients: 1, 3, 7

   .. math::
       P(x) = 2x^2 + 5x + 8, ~ Q(x) = 1x^2 + 3x + 2
In this example, we subtract a 2nd-degree polynomial from another 2nd-degree polynomial.

   // import libraries
   using System;
   using SepalSolver.Math;

   // Example of subtracting polynomials
   double[] poly1 = { 2, 5, 8 }; 
   double[] poly2 = { 1, 3, 2 }; 
   double[] result = Polysub(poly1, poly2);

   // Print the result
   Console.WriteLine($"Resulting Coefficients: {string.Join(", ", result)}");


   Resulting Coefficients: 1, 2, 6

   .. math::
       P(x) = 3x^2 + 2x + 1, ~ x = 2
Evaluation: 3(2)^2 + 2(2) + 1 = 12 + 4 + 1 = 17

   // import libraries
   using System;
   using static SepalSolver.Math;

   // Example of evaluating a polynomial
   double[] coefficients = [3, 2, 1];
   double x = 2;
   double result = Polyval(coefficients, x);

   // Print the result
   Console.WriteLine($"Result at x={x}: {result}");


   Result at x=2: 17

   .. math::
       P(x) = 3x^3 + 4x^2 + 2x + 5, ~ n = 1
Calculation: P'(x) = (3*3)x^2 + (4*2)x + 2 = 9x^2 + 8x + 2

   // import libraries
   using System;
   using SepalSolver.Math;

   // Example of differentiating a polynomial
   double[] coefficients = { 3, 4, 2, 5 };
   int n = 1;
   double[] derivative = Polyder(coefficients, n);

   // Print the result
   Console.WriteLine($"Derivative Coefficients: {string.Join(", ", derivative)}");


   Derivative Coefficients: 9, 8, 2

   .. math::
       P(x) = 3x^2 + 2x + 1, ~ C = 10
Calculation: \int P(x) dx = (3/3)x^3 + (2/2)x^2 + (1/1)x + 10 = x^3 + x^2 + x + 10

   // import libraries
   using System;
   using static SepalSolver.Math;

   // Example of integrating a polynomial
   double[] coefficients = { 3, 2, 1 };
   double C = 10;
   double[] integral = Polyint(coefficients, C);

   // Print the result
   Console.WriteLine($"Integral Coefficients: {string.Join(", ", integral)}");


   Integral Coefficients: 1, 1, 1, 10

   .. math::
      P(x) = x^2 + 2x + 3,~ M(x) = x + 1
In this example, we perform polynomial convolution on two polynomials.
The first polynomial is represented by the coefficients :math:`[1, 2, 3]` and the second polynomial by :math:`[1, 1]`.

   // import libraries
   using System;
   using SepalSolver.Math;

   // Example of performing polynomial convolution
   double[] Polynomial = [ 1, 2, 3 ];
   double[] Multiplier = [ 1, 1 ];
   double[] Product = Conv(Polynomial, Multiplier);
   // Print the result
   Console.WriteLine($"Product: {string.Join(", ", Product)}");


   Product: 1, 3, 5, 3

   .. math::
      P(x) = (2+3i)x^2 + (5-i)x + 3+7i,~ M(x) = (-3+2i)x + 2-i
In this example, we perform polynomial convolution on two polynomials.
The first polynomial is represented by the coefficients :math:`[2+3i, 5-i, 3+7i]` and the second polynomial by :math:`[-3+2i, 2-i]`.

   // import libraries
   using System;
   using SepalSolver.Math;

   // Example of performing polynomial convolution
   Complex[] Polynomial = [ new(2,3), new(5,-1), new(3,7) ];
   Complex[] Multiplier = [ new(-3,2), new(2,-1) ];
   var Product = Conv(Polynomial, Multiplier);
   // Print the result
   Console.WriteLine($"Product: {string.Join(", ", Product)}");


   Product: -12 - 5i ,  -6 + 17i, -14 - 22i,  13 + 11i

