   // Calculate the hyperbolic sine
   double result = Sinh(x);

   // Output the result
   Console.WriteLine($"Sinh({x}) = {result}");
   Console.WriteLine($"Verification: (e^{x} - e^(-{x}))/2 = {(Exp(x) - Exp(-x)) / 2}");


